"use strict";const DEFAULT_TIMEOUT_MS=15e3;function publishLsRequestWithAck(params){const{client:client,content:content,requestId:requestId,topic:topic="/ls_req",responseTopic:responseTopic="/ls_resp",timeoutMs:timeoutMs=DEFAULT_TIMEOUT_MS,extract:extract}=params;if(!client||typeof client.on!=="function"||typeof client.publish!=="function"){return Promise.reject(new Error("MQTT client is not initialized or not connected"))}if(!client.connected){return Promise.reject(new Error("MQTT client is not connected"))}if(typeof client.setMaxListeners==="function"){const current=typeof client.getMaxListeners==="function"?client.getMaxListeners():10;client.setMaxListeners(Math.max(50,current+20))}return new Promise((resolve,reject)=>{let settled=false;let timer;const cleanup=()=>{if(timer){clearTimeout(timer);timer=null}try{client.removeListener("message",onMessage)}catch(_){}};const settle=handler=>{if(settled)return;settled=true;cleanup();try{handler()}catch(e){reject(e)}};const onMessage=(incomingTopic,rawMessage)=>{if(incomingTopic!==responseTopic)return;let parsed;try{parsed=JSON.parse(rawMessage.toString());if(typeof parsed.payload==="string"){try{parsed.payload=JSON.parse(parsed.payload)}catch(_){}}}catch(_){return}if(parsed.request_id!==requestId)return;settle(()=>{try{const result=typeof extract==="function"?extract(parsed):{success:true,response:parsed.payload};resolve(result)}catch(e){reject(e)}})};client.on("message",onMessage);const payload=JSON.stringify(content);client.publish(topic,payload,{qos:1,retain:false},err=>{if(err){settle(()=>reject(new Error(`MQTT publish failed: ${err.message||err}`)))}});timer=setTimeout(()=>{settle(()=>reject(new Error(`Timeout waiting for LS ACK (requestId=${requestId}, ${timeoutMs}ms)`)))},timeoutMs)})}function buildLsEnvelope(ctx,tasks,versionId="25459622483894963"){if(typeof ctx.wsReqNumber!=="number")ctx.wsReqNumber=0;if(typeof ctx.wsTaskNumber!=="number")ctx.wsTaskNumber=0;const requestId=++ctx.wsReqNumber;const envelope={app_id:String(ctx.appID||ctx.mqttAppID||"2220391788200892"),payload:JSON.stringify({epoch_id:generateEpochId(),tasks:tasks,version_id:versionId}),request_id:requestId,type:3};return{envelope:envelope,requestId:requestId}}function buildLsTask(ctx,label,queueName,payload){if(typeof ctx.wsTaskNumber!=="number")ctx.wsTaskNumber=0;const taskId=++ctx.wsTaskNumber;return{failure_count:null,label:String(label),payload:JSON.stringify(payload),queue_name:queueName,task_id:taskId}}function generateEpochId(){const SOMEDAY=1331209219;const now=Date.now();const id=(now-SOMEDAY*1e3)*Math.pow(2,22);return parseInt(id+Math.floor(Math.random()*Math.pow(2,22)))}module.exports={publishLsRequestWithAck:publishLsRequestWithAck,buildLsEnvelope:buildLsEnvelope,buildLsTask:buildLsTask,generateEpochId:generateEpochId};
